-- Audi TT (8N) seed: generated by scripts/generate-seed.mjs from
-- the filled intake template at scripts/cars/audi-tt-8n/, per the import-car skill.
--
-- PREREQUISITE: run 20260929120000_move_seats_count_to_phase_body_dimensions.sql FIRST —
-- section 7 below (PHASE_BODY_DIMENSIONS) writes to phase_body_dimensions.seats_count,
-- which doesn't exist live until that migration runs. generate-seed.mjs's own preflight
-- block doesn't check for this (it only checks brand/body/engine/transmission existence,
-- not arbitrary schema columns) — this is a manual note, not an automated guard.
--
-- REUSE/CREATE summary (reconciled live at generation time):
--   engines: 3 REUSE, 5 NEW (ARY, BVP, BVR, BFV, BHE)
--   transmissions: 4 REUSE, 0 NEW
--   body types: 0 REUSE, 2 NEW (Coupe 2-door, Roadster 2-door)
--   drivetrain systems referenced: haldex_gen1
--   brand: REUSE. model: TT (assumed NEW unless already present).
--
-- Configs: 29 total, one row per 'x' cell across 2 config grid file(s)
-- (configs-Facelift.csv, configs-Pre-facelift.csv) — every FK resolves by code/name via a CTE, never a
-- hand-typed UUID.
--
-- ALIAS DRIFT DETECTED: 2 REUSE engine(s) need a guarded alt_codes UPDATE
--
-- TYPE CASTS: every WITH ... AS (VALUES ...) SELECT ... INSERT block explicitly casts
-- each literal (::integer / ::numeric / ::text) — required by the import-car skill to
-- avoid the all-NULL-column VALUES-CTE type-inference bug (Golf IV/León/Toledo/A3 all
-- hit this on their all-NULL NCAP columns).
--
-- Contains a DESTRUCTIVE step (alt_codes UPDATE, section marked below) — file-only,
-- human-run, NOT executed here.
--
-- Review-only. NOT executed by this script.

do $$
begin
  if to_regclass('public.catalog_brands') is null then
    raise exception 'catalog_brands does not exist — run the catalog_ schema migration first.';
  end if;
  if not exists (select 1 from drivetrain_systems where code = 'haldex_gen1') then
    raise exception 'drivetrain_systems.haldex_gen1 is missing — needed for this car''s configs.';
  end if;
  if (select count(*) from catalog_engines where (code, power_kw) in (
    ('AGU', 110), ('AUQ', 132), ('BAM', 165)
  )) <> 3 then
    raise exception 'One or more REUSE engines are missing live — reconcile is stale, re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'ARY') then
    raise exception 'catalog_engines.ARY already exists — reconcile is stale (was this already seeded?), re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'BVP') then
    raise exception 'catalog_engines.BVP already exists — reconcile is stale (was this already seeded?), re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'BVR') then
    raise exception 'catalog_engines.BVR already exists — reconcile is stale (was this already seeded?), re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'BFV') then
    raise exception 'catalog_engines.BFV already exists — reconcile is stale (was this already seeded?), re-check before running.';
  end if;
  if exists (select 1 from catalog_engines where code = 'BHE') then
    raise exception 'catalog_engines.BHE already exists — reconcile is stale (was this already seeded?), re-check before running.';
  end if;
  if (select count(*) from catalog_transmissions where code in (
    '02J', '02M', '09G', '02E'
  )) <> 4 then
    raise exception 'One or more REUSE transmissions are missing live — reconcile is stale, re-check before running.';
  end if;
end $$;

